public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Integer boxed;
        if (n == 0) {
            boxed = null;
        } else {
            boxed = n;
        }
        int raw = boxed == null ? 0 : boxed;
        System.out.println("今天有 " + raw + " 条小鱼干喵");
        Integer a = 200;
        Integer b = 200;
        System.out.println("两只口袋里的数一样吗：" + a.equals(b));
    }
}

